(async()=>{
const F={name:'sales_incident_report.zip',b64:''};
const LABEL=/^Golden Solution File Uploader$/i;
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const txt=e=>(e.textContent||'').replace(/\s+/g,' ').trim();
const all=()=>[...document.querySelectorAll('body *')];
const lab=()=>all().find(e=>LABEL.test(txt(e)));
if(!lab()){const h=all().find(e=>/^Section 2\s*[-–]\s*Golden Solution and Rubric$/i.test(txt(e))&&e.children.length<4);if(h){h.click();await sleep(900);}}
const L=lab();if(!L){console.error('Uploader label not found');return;}
L.scrollIntoView({block:'center'});
const bin=atob(F.b64);const a=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)a[i]=bin.charCodeAt(i);
const file=new File([a],F.name,{type:'application/zip',lastModified:Date.now()});
const fi=[...document.querySelectorAll('input[type=file]')].find(i=>L.compareDocumentPosition(i)&4);
if(!fi){console.error('No empty upload box after the label. Click x on the old file first, then run again.');return;}
const zone=fi.closest('[role=presentation]')||fi.parentElement;
const dt=new DataTransfer();dt.items.add(file);
for(const t of ['dragenter','dragover','drop']){zone.dispatchEvent(new DragEvent(t,{bubbles:true,cancelable:true,dataTransfer:dt}));await sleep(150);}
await sleep(3000);
const shown=()=>all().some(e=>e.children.length===0&&txt(e)===F.name&&(L.compareDocumentPosition(e)&4));
if(!shown()){const d2=new DataTransfer();d2.items.add(file);fi.files=d2.files;fi.dispatchEvent(new Event('input',{bubbles:true}));fi.dispatchEvent(new Event('change',{bubbles:true}));await sleep(3000);}
console.log(shown()?'UPLOADED: '+F.name+' now shows under the uploader':'NOT UPLOADED: drag the zip in by hand');
})();